const upsertGameCourse = `-- name: UpsertGameCourse :one

INSERT INTO game_courses (code, position, title, published_at)
VALUES ($1, $2, $3, $4)
ON CONFLICT (code) DO UPDATE
SET position = EXCLUDED.position, title = EXCLUDED.title, published_at = EXCLUDED.published_at
RETURNING id
`

type UpsertGameCourseParams struct {
	Code        string          `json:"code"`
	Position    int32           `json:"position"`
	Title       json.RawMessage `json:"title"`
	PublishedAt sql.NullTime    `json:"published_at"`
}

// ----- the import of a course (admins) -----
func (q *Queries) UpsertGameCourse(ctx context.Context, arg UpsertGameCourseParams) (int64, error) {
	row := q.db.QueryRowContext(ctx, upsertGameCourse,
		arg.Code,
		arg.Position,
		arg.Title,
		arg.PublishedAt,
	)
	var id int64
	err := row.Scan(&id)
	return id, err
}

const upsertGameLessonResult = `-- name: UpsertGameLessonResult :one
INSERT INTO game_lesson_results (user_id, lesson_id, best_stars, best_first_try, plays, first_completed_at, last_played_at)
VALUES ($1, $2, $3, $4, 1, $5, $5)
ON CONFLICT (user_id, lesson_id) DO UPDATE
SET best_stars = GREATEST(game_lesson_results.best_stars, EXCLUDED.best_stars),
    best_first_try = GREATEST(game_lesson_results.best_first_try, EXCLUDED.best_first_try),
    plays = game_lesson_results.plays + 1,
    last_played_at = EXCLUDED.last_played_at
RETURNING best_stars
`

type UpsertGameLessonResultParams struct {
	UserID   int64     `json:"user_id"`
	LessonID int64     `json:"lesson_id"`
	Stars    int16     `json:"stars"`
	FirstTry int16     `json:"first_try"`
	PlayedAt time.Time `json:"played_at"`
}

// Keeps the best play of the lesson.
func (q *Queries) UpsertGameLessonResult(ctx context.Context, arg UpsertGameLessonResultParams) (int16, error) {
	row := q.db.QueryRowContext(ctx, upsertGameLessonResult,
		arg.UserID,
		arg.LessonID,
		arg.Stars,
		arg.FirstTry,
		arg.PlayedAt,
	)
	var best_stars int16
	err := row.Scan(&best_stars)
	return best_stars, err
}
